customScripts.celebration_slider:
(function(root, ctx){
  if (!root) return;
  var initKey = 'mfInit_celebration_slider';
  if (root.dataset && root.dataset[initKey] === '1') return;
  if (root.dataset) root.dataset[initKey] = '1';

  var container = root.querySelector('.rc-slider-container');
  if (!container) return;

  var track = container.querySelector('.rc-slider-track');
  var slides = container.querySelectorAll('.rc-slide');
  var prevBtn = container.querySelector('.rc-slider-prev');
  var nextBtn = container.querySelector('.rc-slider-next');
  var dotsContainer = container.querySelector('.rc-slider-dots');

  if (!track || !slides.length || !dotsContainer) return;

  var currentIndex = 0;
  var slidesPerView = 3;
  var autoSlideInterval = null;
  var touchStartX = 0;
  var touchEndX = 0;

  function updateSlidesPerView(){
    var rect = (track && track.parentElement && track.parentElement.getBoundingClientRect)
             ? track.parentElement.getBoundingClientRect() : null;
    var w = (rect && rect.width) ? rect.width : (window.innerWidth || 1024);
    if (w <= 480) slidesPerView = 1;
    else if (w <= 780) slidesPerView = 2;
    else if (w <= 1200) slidesPerView = 3;
    else slidesPerView = 4;  // rc-container-width
  }

  function getMaxIndex(){
    return Math.max(0, slides.length - slidesPerView);
  }

  function updateDots(){
    var dots = dotsContainer.querySelectorAll('.rc-dot');
    dots.forEach(function(dot, i){
      dot.classList.toggle('active', i === currentIndex);
    });
  }

  function updateSlider(){
    var slideWidth = 100 / slidesPerView;
    track.style.transform = 'translateX(-' + (currentIndex * slideWidth) + '%)';
    updateDots();
  }

  function goToSlide(index){
    currentIndex = Math.max(0, Math.min(index, getMaxIndex()));
    updateSlider();
  }

  function nextSlide(){
    currentIndex = currentIndex >= getMaxIndex() ? 0 : currentIndex + 1;
    updateSlider();
  }

  function prevSlide(){
    currentIndex = currentIndex <= 0 ? getMaxIndex() : currentIndex - 1;
    updateSlider();
  }

  function createDots(){
    dotsContainer.innerHTML = '';
    var totalDots = getMaxIndex() + 1;
    for (var i = 0; i < totalDots; i++) {
      var dot = document.createElement('button');
      dot.type = 'button';
      dot.className = 'rc-dot' + (i === 0 ? ' active' : '');
      dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
      (function(index){
        dot.addEventListener('click', function(){ goToSlide(index); });
      })(i);
      dotsContainer.appendChild(dot);
    }
  }

  function stopAutoSlide(){
    if (autoSlideInterval) {
      clearInterval(autoSlideInterval);
      autoSlideInterval = null;
    }
  }

  function startAutoSlide(){
    stopAutoSlide();
    autoSlideInterval = window.setInterval(nextSlide, 5000);
  }

  function handleResize(){
    updateSlidesPerView();
    currentIndex = Math.min(currentIndex, getMaxIndex());
    createDots();
    updateSlider();
  }

  function onPrevClick(){ prevSlide(); startAutoSlide(); }
  function onNextClick(){ nextSlide(); startAutoSlide(); }
  function onMouseEnter(){ stopAutoSlide(); }
  function onMouseLeave(){ startAutoSlide(); }
  function onTouchStart(e){
    touchStartX = e.changedTouches[0].screenX;
    stopAutoSlide();
  }
  function onTouchEnd(e){
    touchEndX = e.changedTouches[0].screenX;
    var diff = touchStartX - touchEndX;
    if (Math.abs(diff) > 50) {
      if (diff > 0) nextSlide();
      else prevSlide();
    }
    startAutoSlide();
  }

  if (prevBtn) prevBtn.addEventListener('click', onPrevClick);
  if (nextBtn) nextBtn.addEventListener('click', onNextClick);
  container.addEventListener('mouseenter', onMouseEnter);
  container.addEventListener('mouseleave', onMouseLeave);
  container.addEventListener('touchstart', onTouchStart, { passive: true });
  container.addEventListener('touchend', onTouchEnd, { passive: true });
  window.addEventListener('resize', handleResize);

  updateSlidesPerView();
  createDots();
  updateSlider();
  startAutoSlide();

  if (ctx && typeof ctx.registerCleanup === 'function') {
    ctx.registerCleanup([
      function(){ stopAutoSlide(); },
      function(){ if (prevBtn) prevBtn.removeEventListener('click', onPrevClick); },
      function(){ if (nextBtn) nextBtn.removeEventListener('click', onNextClick); },
      function(){ container.removeEventListener('mouseenter', onMouseEnter); },
      function(){ container.removeEventListener('mouseleave', onMouseLeave); },
      function(){ container.removeEventListener('touchstart', onTouchStart); },
      function(){ container.removeEventListener('touchend', onTouchEnd); },
      function(){ window.removeEventListener('resize', handleResize); }
    ]);
  }
})(window.__mfCurrentScriptRoot, window.__mfScriptContext);

