settings.customCss:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Lora:ital,wght@0,400;0,500;0,600;1,400&display=swap');

.mfp.romantic-celebration {
  --rc-cream: #fef9f5;
  --rc-blush: #fff0eb;
  --rc-rose: #c45c6a;
  --rc-rose-light: #e8919b;
  --rc-rose-dark: #a34854;
  --rc-rose-pale: #f5d5d8;
  --rc-gold: #c9a87c;
  --rc-gold-light: #e0c9a8;
  --rc-gold-dark: #a08050;
  --rc-green: #5a8c5a;
  --rc-green-light: #7aac7a;
  --rc-text: #3d2c29;
  --rc-text-muted: #6b5a56;
  --rc-white: #ffffff;
  --rc-border: #e8d5d0;
  --rc-shadow: 0 8px 40px rgba(164, 72, 84, 0.12);
  --rc-shadow-lg: 0 20px 60px rgba(164, 72, 84, 0.18);
  --rc-radius: 20px;
  --rc-radius-sm: 12px;
  min-height: 100vh;
  background: linear-gradient(180deg, var(--rc-cream) 0%, var(--rc-blush) 40%, var(--rc-cream) 100%);
  font-family: 'Lora', Georgia, serif;
  color: var(--rc-text);
  position: relative;
  overflow-x: hidden;
  padding: 40px 20px;
}

.mfp.romantic-celebration * { box-sizing: border-box; }

/* Ambient roses */
.rc-ambient {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.rc-rose {
  position: absolute;
  width: 120px;
  height: 120px;
  opacity: 0.08;
  background: radial-gradient(circle, var(--rc-rose) 0%, transparent 70%);
  border-radius: 50%;
}

.rc-rose-1 { top: 5%; left: 5%; width: 150px; height: 150px; }
.rc-rose-2 { top: 15%; right: 8%; width: 100px; height: 100px; }
.rc-rose-3 { bottom: 20%; left: 3%; width: 130px; height: 130px; }
.rc-rose-4 { bottom: 10%; right: 5%; width: 110px; height: 110px; }

/* Floating petals */
.rc-petals {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.rc-petal {
  position: absolute;
  width: 18px;
  height: 22px;
  background: linear-gradient(135deg, var(--rc-rose-light) 0%, var(--rc-rose) 100%);
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  opacity: 0.35;
  animation: petal-fall linear infinite;
}

.rc-petal::before {
  content: '';
  position: absolute;
  inset: 25%;
  background: rgba(255,255,255,0.4);
  border-radius: inherit;
}

.rc-petal.p1 { left: 8%; animation-duration: 18s; animation-delay: 0s; }
.rc-petal.p2 { left: 22%; animation-duration: 22s; animation-delay: 3s; }
.rc-petal.p3 { left: 45%; animation-duration: 16s; animation-delay: 6s; }
.rc-petal.p4 { left: 60%; animation-duration: 20s; animation-delay: 2s; }
.rc-petal.p5 { left: 75%; animation-duration: 17s; animation-delay: 5s; }
.rc-petal.p6 { left: 88%; animation-duration: 21s; animation-delay: 1s; }

@keyframes petal-fall {
  0% { transform: translateY(-20px) rotate(0deg); opacity: 0; }
  10% { opacity: 0.35; }
  90% { opacity: 0.35; }
  100% { transform: translateY(100vh) rotate(360deg); opacity: 0; }
}

/* Frame */
.rc-frame {
  position: relative;
  z-index: 1;
  max-width: 900px;
  margin: 0 auto;
}

/* Gold lines */
.rc-gold-line {
  height: 4px;
  background: linear-gradient(90deg, transparent 0%, var(--rc-gold-light) 20%, var(--rc-gold) 50%, var(--rc-gold-light) 80%, transparent 100%);
  border-radius: 2px;
}

.rc-gold-line-top { margin-bottom: 0; }
.rc-gold-line-bottom { margin-top: 0; }

/* Header */
.rc-header {
  background: linear-gradient(180deg, var(--rc-white) 0%, var(--rc-blush) 100%);
  padding: 40px 32px 32px;
  text-align: center;
  border-radius: var(--rc-radius) var(--rc-radius) 0 0;
  border: 1px solid var(--rc-border);
  border-bottom: none;
}

.rc-monogram {
  width: 80px;
  height: 80px;
  margin: 0 auto 20px;
  color: var(--rc-rose);
}

.rc-monogram svg {
  width: 100%;
  height: 100%;
}

.rc-title-block {
  margin-bottom: 24px;
}

.rc-eyebrow {
  display: block;
  font-family: 'Lora', serif;
  font-size: 13px;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--rc-text-muted);
  margin-bottom: 8px;
}

.rc-title {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 42px;
  font-weight: 600;
  font-style: italic;
  color: var(--rc-rose-dark);
  margin: 0;
  line-height: 1.2;
}

/* Event info */
.rc-event-info {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.rc-event-date,
.rc-event-time {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--rc-text);
  font-size: 15px;
}

.rc-date-icon,
.rc-time-icon {
  width: 20px;
  height: 20px;
  color: var(--rc-gold);
}

.rc-date-icon svg,
.rc-time-icon svg {
  width: 100%;
  height: 100%;
}

.rc-event-divider {
  width: 1px;
  height: 24px;
  background: var(--rc-border);
}

.rc-venue-block {
  margin-bottom: 20px;
}

.rc-venue-name {
  display: block;
  font-family: 'Playfair Display', serif;
  font-size: 18px;
  font-weight: 500;
  color: var(--rc-text);
  margin-bottom: 4px;
}

.rc-venue-location {
  display: block;
  font-size: 14px;
  color: var(--rc-text-muted);
  font-style: italic;
}

/* Ornament */
.rc-ornament {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.rc-ornament span {
  width: 6px;
  height: 6px;
  background: var(--rc-gold);
  border-radius: 50%;
}

.rc-ornament span:nth-child(2) {
  width: 10px;
  height: 10px;
  background: var(--rc-rose);
}

/* Main */
.rc-main {
  background: transparent;
}

.rc-card {
  position: relative;
  background: var(--rc-white);
  border-radius: 0 0 var(--rc-radius) var(--rc-radius);
  border: 1px solid var(--rc-border);
  border-top: none;
  box-shadow: var(--rc-shadow-lg);
  overflow: hidden;
}

/* Card corners */
.rc-card-corner {
  position: absolute;
  width: 40px;
  height: 40px;
  pointer-events: none;
}

.rc-card-corner::before,
.rc-card-corner::after {
  content: '';
  position: absolute;
  background: var(--rc-gold-light);
}

.rc-card-corner.tl { top: 12px; left: 12px; }
