  border: 1px solid var(--rc-border);
  border-radius: var(--rc-radius-sm);
  background: var(--rc-white);
  color: var(--rc-text);
  transition: all 0.3s ease;
}

.mfp.romantic-celebration .mf-input:focus,
.mfp.romantic-celebration .mf-select:focus,
.mfp.romantic-celebration .mf-textarea:focus {
  outline: none;
  border-color: var(--rc-rose);
  box-shadow: 0 0 0 3px rgba(196, 92, 106, 0.15);
}

.mfp.romantic-celebration .mf-input::placeholder,
.mfp.romantic-celebration .mf-textarea::placeholder {
  color: var(--rc-text-muted);
  font-style: italic;
}

/* Radio/Checkbox styling */
.mfp.romantic-celebration .mf-radio-group,
.mfp.romantic-celebration .mf-checkbox-group {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.mfp.romantic-celebration .mf-radio-option,
.mfp.romantic-celebration .mf-checkbox-option {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  background: var(--rc-blush);
  border: 1px solid var(--rc-border);
  border-radius: var(--rc-radius-sm);
  cursor: pointer;
  transition: all 0.3s ease;
}

.mfp.romantic-celebration .mf-radio-option:hover,
.mfp.romantic-celebration .mf-checkbox-option:hover {
  border-color: var(--rc-rose);
  background: var(--rc-rose-pale);
}

.mfp.romantic-celebration .mf-radio-option.selected,
.mfp.romantic-celebration .mf-checkbox-option.selected {
  border-color: var(--rc-rose);
  background: var(--rc-rose-pale);
}

/* Row grid */
.mfp.romantic-celebration .mf-row {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 20px;
}

.mfp.romantic-celebration .mf-col-6 { grid-column: span 6; }
.mfp.romantic-celebration .mf-col-12 { grid-column: span 12; }

